function recentTable(documents=allDocuments().slice(0,3)) {
  return `<div class="table-panel"><table class="data-table"><thead><tr><th>${L('Название документа','Құжат атауы')}</th><th class="mobile-hide">${L('Обновлён','Жаңартылған')}</th><th>${L('Статус','Күйі')}</th><th><span class="sr-only">${L('Открыть','Ашу')}</span></th></tr></thead><tbody>${documents.map(d=>`<tr><td><div class="doc-cell"><span class="doc-icon ${d.style==='green'?'green':d.style==='peach'?'peach':''}">${icon(d.type==='rp'?'file':'books')}</span><div><strong>${e(d.title)}</strong><small>${e(d.subtitle || L('Учебный материал','Оқу материалы'))}</small></div></div></td><td class="dim mobile-hide">${formatDate(d.date)}</td><td><span class="pill ${d.type==='rp'?'orange':'gray'}">${L(d.type==='rp'?'На проверке':'Готово',d.type==='rp'?'Тексеруде':'Дайын')}</span></td><td><button class="row-action" data-action="open-doc" data-id="${e(d.id)}" aria-label="${L('Открыть','Ашу')}: ${e(d.title)}">${icon('upRight')}</button></td></tr>`).join('')}</tbody></table></div>`;
}
function stat(label,value,delta,note,name) { return `<div class="stat"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon">${icon(name)}</span></div><div class="stat-value"><strong>${value}</strong><span>${delta}</span></div><div class="stat-note">${note}</div></div>`; }
function renderCalendar(){
  const monthsRu=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
  const monthsKz=['Қаңтар','Ақпан','Наурыз','Сәуір','Мамыр','Маусым','Шілде','Тамыз','Қыркүйек','Қазан','Қараша','Желтоқсан'];
  const days=new Date(state.year,state.month+1,0).getDate(), first=(new Date(state.year,state.month,1).getDay()+6)%7, previous=new Date(state.year,state.month,0).getDate();
  let cells=L(['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],['Дс','Сс','Ср','Бс','Жм','Сн','Жс']).map(day=>`<span class="weekday">${day}</span>`).join('');
  for(let i=0;i<first;i++) cells+=`<span class="calendar-day muted">${previous-first+i+1}</span>`;
  for(let i=1;i<=days;i++) cells+=`<button class="calendar-day ${state.selectedDay===i?'selected':''} ${[13,16,20,23,27].includes(i)?'event':''}" data-action="calendar-day" data-day="${i}" aria-label="${i} ${L(monthsRu[state.month],monthsKz[state.month])}" aria-pressed="${state.selectedDay===i}">${i}</button>`;
  const trailing=(7-(first+days)%7)%7;
  for(let i=1;i<=trailing;i++) cells+=`<span class="calendar-day muted">${i}</span>`;
  const sampleDay=state.month===9&&state.year===2026&&[13,16,20,23,27].includes(state.selectedDay);
  return `<div class="panel-head" style="margin:0"><span class="calendar-month">${L(monthsRu[state.month],monthsKz[state.month])} <span style="color:#a4ad95;font-weight:400">${state.year}</span></span><div class="calendar-nav"><button data-action="calendar-month" data-dir="-1" aria-label="${L('Предыдущий месяц','Алдыңғы ай')}">${icon('back')}</button><button data-action="calendar-month" data-dir="1" aria-label="${L('Следующий месяц','Келесі ай')}">${icon('chevron')}</button></div></div><div class="calendar-grid">${cells}</div><div class="schedule-head"><span>${L('План на','Жоспар')} ${state.selectedDay} ${L(['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'][state.month],monthsKz[state.month].toLowerCase())}</span><span style="color:#a6b093;font-size:9px;font-weight:400">${sampleDay?'3':'0'} ${L('события','оқиға')}</span></div>${sampleDay?`<div class="schedule-item"><span class="time-col">09:00</span><div class="schedule-details"><strong>${L('Основы программирования','Бағдарламалау негіздері')}</strong><span>${L('ПО-23-1 · кабинет 304','БҚ-23-1 · 304 кабинет')}</span></div></div><div class="schedule-item"><span class="time-col">11:30</span><div class="schedule-details purple"><strong>${L('Практикум по веб-разработке','Веб-әзірлеу практикумы')}</strong><span>${L('ПО-24-1 · кабинет 208','БҚ-24-1 · 208 кабинет')}</span></div></div><div class="schedule-item"><span class="time-col">14:00</span><div class="schedule-details orange"><strong>${L('Методический час','Әдістемелік сағат')}</strong><span>${L('Новые форматы обучения','Оқытудың жаңа форматтары')}</span></div></div>`:`<p class="calendar-small-note">${L('На этот день событий нет. Можно посвятить время новой идее.','Бұл күні оқиға жоқ. Жаңа идеяға уақыт бөлуге болады.')}</p>`}`;
}

function detectTopic(topic){ const text=topic.toLowerCase(); if(/sql|баз|деректер/.test(text))return 'sql'; if(/html|css|веб|web|сайт/.test(text))return 'web'; if(/python|пайтон|алгоритм|программ|бағдарлам/.test(text))return 'python'; if(/безопас|қауіп|security|кибер/.test(text))return 'security'; return 'ai'; }
function topicData(kind){
  const data={
    web:{ definition:L('HTML задаёт структуру страницы, а CSS определяет её внешний вид. Браузер объединяет разметку и стили в интерфейс, с которым взаимодействует пользователь.','HTML беттің құрылымын анықтайды, ал CSS оның сыртқы көрінісін реттейді. Браузер белгілеу мен стильді пайдаланушы интерфейсіне біріктіреді.'),concepts:[L('Семантика: заголовки, навигация, основной контент.','Семантика: тақырыптар, навигация, негізгі мазмұн.'),L('Блочная модель: контент, padding, border и margin.','Блок моделі: мазмұн, padding, border және margin.'),L('Flexbox и Grid: расположение элементов на странице.','Flexbox және Grid: бет элементтерінің орналасуы.'),L('Адаптивность: интерфейс для разных размеров экрана.','Бейімделу: әртүрлі экран өлшемдеріне арналған интерфейс.')],practice:L('Создайте страницу «О себе»: заголовок h1, абзац, список интересов и кнопку. Подключите CSS, добавьте отступы и расположите карточки через Grid. Проверьте страницу на ширине 375 и 1280 пикселей.','«Өзім туралы» бетін жасаңыз: h1 тақырыбы, абзац, қызығушылықтар тізімі және батырма. CSS қосып, бос орындарды реттеңіз және карточкаларды Grid арқылы орналастырыңыз. Бетті 375 және 1280 пиксель енінде тексеріңіз.'),question:L('Чем padding отличается от margin? Почему на странице важна семантика?','Padding пен margin айырмашылығы қандай? Бет семантикасы не үшін маңызды?'),criterion:L('Структура HTML корректна; стили подключены; элементы не перекрываются на узком экране.','HTML құрылымы дұрыс; стильдер қосылған; тар экранда элементтер қабаттаспайды.'),example:'<h1>My first page</h1>\n<style>h1 { color: #4b55e8; }</style>'},
    sql:{definition:L('Реляционная база данных хранит информацию в таблицах. SQL позволяет выбирать, добавлять и изменять записи. Первичный ключ уникально определяет строку, а внешний связывает таблицы.','Реляциялық деректер базасы ақпаратты кестелерде сақтайды. SQL жазбаларды таңдауға, қосуға және өзгертуге мүмкіндік береді. Бастапқы кілт жолды бірегей анықтайды, ал сыртқы кілт кестелерді байланыстырады.'),concepts:[L('Таблица, строка, столбец и тип данных.','Кесте, жол, баған және деректер түрі.'),L('SELECT и FROM: получение данных.','SELECT және FROM: деректерді алу.'),L('WHERE и ORDER BY: фильтрация и сортировка.','WHERE және ORDER BY: сүзу және сұрыптау.'),L('PRIMARY KEY и FOREIGN KEY: идентификация и связи.','PRIMARY KEY және FOREIGN KEY: сәйкестендіру және байланыстар.')],practice:L('Спроектируйте таблицу Students с полями id, name, group_name и score. Напишите запрос, который выводит имена студентов с баллом выше 80 и сортирует их по убыванию результата.','id, name, group_name және score өрістері бар Students кестесін жобалаңыз. Балы 80-нен жоғары студенттердің атын көрсетіп, нәтижені кему ретімен сұрыптайтын сұрау жазыңыз.'),question:L('Для чего нужен первичный ключ? В каком порядке работают WHERE и ORDER BY?','Бастапқы кілт не үшін керек? WHERE және ORDER BY қалай қолданылады?'),criterion:L('Выбраны правильные столбцы; условие записано через WHERE; используется ORDER BY score DESC.','Дұрыс бағандар таңдалған; шарт WHERE арқылы жазылған; ORDER BY score DESC қолданылған.'),example:'SELECT name, score\nFROM Students\nWHERE score > 80\nORDER BY score DESC;'},
    python:{definition:L('Программа — последовательность инструкций для решения задачи. В Python данные хранятся в переменных, условия задают выбор действий, а циклы повторяют операции.','Бағдарлама — есепті шешуге арналған нұсқаулар тізбегі. Python тілінде деректер айнымалыларда сақталады, шарттар әрекетті таңдайды, ал циклдер амалдарды қайталайды.'),concepts:[L('Переменные и базовые типы: int, float, str, bool.','Айнымалылар және негізгі түрлер: int, float, str, bool.'),L('Условия if / elif / else.','if / elif / else шарттары.'),L('Циклы for и while, обход списка.','for және while циклдері, тізіммен жұмыс.'),L('Функции: параметры, результат и повторное использование.','Функциялар: параметрлер, нәтиже және қайта пайдалану.')],practice:L('Напишите функцию average_score, которая принимает список оценок и возвращает среднее значение. Проверьте её на [75, 90, 85]. Предусмотрите случай пустого списка.','Бағалар тізімін қабылдап, орташа мәнін қайтаратын average_score функциясын жазыңыз. Оны [75, 90, 85] тізімімен тексеріңіз. Бос тізім жағдайын ескеріңіз.'),question:L('Когда удобнее использовать цикл for? Чем возврат значения отличается от print?','For циклін қашан қолданған ыңғайлы? Мәнді қайтару мен print айырмашылығы қандай?'),criterion:L('Функция использует sum и len или цикл; не делит на ноль; результат для примера — около 83.33.','Функция sum және len немесе циклді қолданады; нөлге бөлмейді; мысал нәтижесі шамамен 83.33.'),example:'def average_score(scores):\n    return sum(scores) / len(scores) if scores else 0'},
    security:{definition:L('Кибербезопасность помогает сохранить конфиденциальность, целостность и доступность данных. Надёжный пароль, проверка ссылок и резервные копии снижают повседневные риски.','Киберқауіпсіздік деректердің құпиялылығын, тұтастығын және қолжетімділігін сақтайды. Сенімді құпиясөз, сілтемелерді тексеру және сақтық көшірмелер күнделікті тәуекелді азайтады.'),concepts:[L('Уникальные длинные пароли и менеджер паролей.','Бірегей ұзын құпиясөздер және құпиясөз менеджері.'),L('Двухфакторная аутентификация.','Екі факторлы аутентификация.'),L('Признаки фишинга: срочность, поддельный домен, вложение.','Фишинг белгілері: асықтыру, жалған домен, тіркеме.'),L('Резервное копирование и обновления.','Сақтық көшірмелер және жаңартулар.')],practice:L('Сравните два учебных письма: обычное уведомление колледжа и сообщение «Срочно подтвердите пароль». Найдите три признака фишинга и объясните, как проверить отправителя, не переходя по ссылке.','Колледж хабарламасы мен «Құпиясөзді дереу растаңыз» деген екі оқу хатын салыстырыңыз. Фишингтің үш белгісін тауып, сілтемені ашпай жіберушіні тексеру жолын түсіндіріңіз.'),question:L('Почему пароль нельзя передавать в чате? Что даёт второй фактор?','Құпиясөзді чатта неге беруге болмайды? Екінші фактор не береді?'),criterion:L('Указаны подозрительные признаки; выбран безопасный способ проверки; пароль не отправляется.','Күдікті белгілер көрсетілген; қауіпсіз тексеру тәсілі таңдалған; құпиясөз жіберілмейді.'),example:'college.example ≠ co11ege.example'},
    ai:{definition:L('Искусственный интеллект — набор методов для решения задач, требующих распознавания закономерностей. Модель учится на примерах, но её ответы могут содержать ошибки и требуют проверки.','Жасанды интеллект — заңдылықтарды тануға арналған әдістер жиынтығы. Модель мысалдардан үйренеді, бірақ жауаптарында қате болуы мүмкін және тексеру қажет.'),concepts:[L('Данные, обучение и применение модели.','Деректер, оқыту және модельді қолдану.'),L('Классификация, прогнозирование и генерация.','Жіктеу, болжау және генерация.'),L('Хороший запрос: задача, контекст и формат результата.','Жақсы сұрау: міндет, контекст және нәтиже форматы.'),L('Проверка фактов, ограничений и источников.','Фактілерді, шектеулерді және дереккөздерді тексеру.')],practice:L('Составьте запрос для помощника, который должен объяснить сложную тему первокурснику. Укажите аудиторию, желаемую длину, пример и критерии проверки. Сравните с запросом без контекста.','Күрделі тақырыпты бірінші курс студентіне түсіндіретін көмекшіге сұрау құрастырыңыз. Аудиторияны, көлемді, мысалды және тексеру өлшемдерін көрсетіңіз. Контекстсіз сұраумен салыстырыңыз.'),question:L('Почему ответы модели нужно проверять? Как контекст влияет на ответ?','Модель жауабын неге тексеру керек? Контекст жауапқа қалай әсер етеді?'),criterion:L('Запрос содержит задачу и аудиторию; задан формат; указано, как проверить результат.','Сұрауда міндет пен аудитория бар; формат берілген; нәтижені тексеру тәсілі көрсетілген.'),example:L('Объясни цикл for студенту 1 курса. Дай пример на Python и один вопрос для самопроверки.','For циклін 1 курс студентіне түсіндір. Python мысалын және өзін тексеруге бір сұрақ бер.')}
  }; return data[kind] || data.ai;
}
function lessonContent(topic,kind,options={}){
  const d=topicData(kind),goal=options.goal || L('Понять основные понятия и применить их в практическом задании.','Негізгі ұғымдарды түсініп, практикалық тапсырмада қолдану.');
  return `<div class="doc-kicker">ORBIT / ${L('Учебное занятие','Оқу сабағы')}</div><h2>${e(topic)}</h2><div class="document-meta"><span class="pill purple">${e(options.course || '1–2')} ${L('курс','курс')}</span><span class="pill">${options.minutes || 90} ${L('минут','минут')}</span><span class="pill gray">${e(options.specialty || L('Информационные технологии','Ақпараттық технологиялар'))}</span></div><h3>01. ${L('Результат обучения','Оқу нәтижесі')}</h3><p>${e(goal)}</p><h3>02. ${L('Объяснение темы','Тақырыпты түсіндіру')}</h3><p>${d.definition}</p><ul>${d.concepts.map(x=>`<li>${x}</li>`).join('')}</ul><h3>03. ${L('Разбираем на примере','Мысалды талдау')}</h3><p><code style="display:block;white-space:pre-wrap;background:#f3f5ec;padding:15px;border-radius:9px;font-size:11px;color:#748760">${e(d.example)}</code></p><h3>04. ${L('Практическое задание','Практикалық тапсырма')}</h3><p>${d.practice}</p><h3>05. ${L('Самопроверка','Өзін тексеру')}</h3><p>${d.question}</p><h3>${L('Критерии оценивания','Бағалау өлшемдері')}</h3><p>${d.criterion}</p><p class="doc-tip">${L('Демонстрационный материал из локального набора примеров. Перед использованием преподаватель проверяет содержание.','Жергілікті мысалдар жиынтығынан демонстрациялық материал. Қолданар алдында оқытушы мазмұнды тексереді.')}</p>`;
}
function programmeContent(options){
  const {topic,hours,specialty,type}=options;
  const kind=detectTopic(topic),data=topicData(kind),count=type==='qmj'?3:Math.min(6,Number(hours)),total=Number(hours);
  const titles=type==='qmj'?[L('Начало занятия','Сабақтың басы'),L('Основная часть','Негізгі бөлім'),L('Рефлексия и оценивание','Рефлексия және бағалау')]:[L('Введение и основные понятия','Кіріспе және негізгі ұғымдар'),...data.concepts.map(x=>x.replace(/\.$/,'')),L('Итоговая практика и оценивание','Қорытынды практика және бағалау')];
  const short=type==='qmj';
  const minutes=Number(options.minutes || 90);
  const durations=short?[Math.round(minutes/6),Math.round(minutes*2/3),minutes-Math.round(minutes/6)-Math.round(minutes*2/3)]:Array.from({length:count},(_,i)=>Math.floor(total/count)+(i<total%count?1:0));
  const name=type==='ktp'?L('Календарно-тематический план','Күнтізбелік-тақырыптық жоспар'):short?L('Краткосрочный план занятия','Қысқа мерзімді сабақ жоспары'):L('Рабочая учебная программа','Жұмыс оқу бағдарламасы');
  return `<div class="doc-kicker">ORBIT / ${name}</div><h2>${e(topic)}</h2><div class="document-meta"><span class="pill">${short?minutes+' '+L('минут','минут'):total+' '+L('часов','сағат')}</span><span class="pill purple">${e(specialty)}</span><span class="pill orange">${L('Проект документа','Құжат жобасы')}</span></div><h3>1. ${L('Общие положения','Жалпы ережелер')}</h3><p>${L('Программа предназначена для студентов технического колледжа. Обучение объединяет теоретические основы, разбор примеров и самостоятельную практику.','Бағдарлама техникалық колледж студенттеріне арналған. Оқыту теориялық негіздерді, мысалдарды талдауды және өздігінен практиканы біріктіреді.')}</p><h3>2. ${L('Ожидаемые результаты','Күтілетін нәтижелер')}</h3><ul><li>${L('Объясняет основные понятия темы.','Тақырыптың негізгі ұғымдарын түсіндіреді.')}</li><li>${L('Выполняет практическую задачу и обосновывает решение.','Практикалық тапсырманы орындап, шешімін негіздейді.')}</li><li>${L('Проверяет результат по заданным критериям.','Нәтижені берілген өлшемдер бойынша тексереді.')}</li></ul><h3>3. ${short?L('Ход занятия','Сабақ барысы'):L('Тематический план','Тақырыптық жоспар')}</h3><table><thead><tr><th>№</th><th>${short?L('Этап','Кезең'):L('Раздел / тема','Бөлім / тақырып')}</th><th>${short?L('Мин.','Мин.'):L('Часы','Сағат')}</th><th>${L('Форма работы','Жұмыс түрі')}</th></tr></thead><tbody>${durations.map((duration,i)=>`<tr><td>${i+1}</td><td>${e(titles[i])}</td><td>${duration}</td><td>${L(i%2?'Практическое задание':'Обсуждение и разбор примера',i%2?'Практикалық тапсырма':'Талқылау және мысалды талдау')}</td></tr>`).join('')}<tr><td colspan="2"><strong>${L('Итого','Барлығы')}</strong></td><td><strong>${durations.reduce((a,b)=>a+b,0)}</strong></td><td></td></tr></tbody></table><h3>4. ${L('Практическая работа','Практикалық жұмыс')}</h3><p>${data.practice}</p><h3>5. ${L('Контроль и оценивание','Бақылау және бағалау')}</h3><p>${data.criterion}</p><p>${L('Оценивание: понимание темы — 30%, выполнение задания — 50%, объяснение решения — 20%.','Бағалау: тақырыпты түсіну — 30%, тапсырманы орындау — 50%, шешімді түсіндіру — 20%.')}</p><h3>6. ${L('Ресурсы и оборудование','Ресурстар және жабдық')}</h3><p>${L('Компьютер, учебные примеры, материалы электронной библиотеки колледжа.','Компьютер, оқу мысалдары, колледждің электрондық кітапхана материалдары.')}</p><p class="doc-tip">${L('Демонстрационная структура. Утверждённый шаблон колледжа не предоставлен; этот проект можно использовать для показа процесса подготовки.','Демонстрациялық құрылым. Колледждің бекітілген үлгісі берілмеген; жоба дайындау процесін көрсетуге арналған.')}</p>`;
}
function presentationContent(topic,kind,options={}){ const d=topicData(kind); const slides=[{title:topic,text:d.definition},{title:L('Что нужно понять','Нені түсіну керек'),text:d.concepts.slice(0,2).join('\n')},{title:L('От идеи к практике','Идеядан практикаға'),text:d.example},{title:L('Попробуйте самостоятельно','Өзіңіз орындап көріңіз'),text:d.practice},{title:L('Проверьте себя','Өзіңізді тексеріңіз'),text:d.question}]; return `<div class="doc-kicker">ORBIT / ${L('План презентации','Презентация жоспары')}</div><h2>${e(topic)}</h2>${slides.map((slide,i)=>`<section class="slide-preview"><span class="slide-no">SLIDE 0${i+1} / 05</span><h3>${e(slide.title)}</h3><p style="white-space:pre-wrap">${e(slide.text)}</p></section>`).join('')}<p class="doc-tip">${L('Демонстрационный план слайдов. Можно распечатать или скачать как документ.','Слайдтардың демонстрациялық жоспары. Басып шығаруға немесе құжат ретінде жүктеуге болады.')}</p>`; }
function assignmentContent(topic,kind,options={}){ const d=topicData(kind); return `<div class="doc-kicker">ORBIT / ${L('Практическое задание','Практикалық тапсырма')}</div><h2>${e(topic)}</h2><div class="document-meta"><span class="pill">${options.minutes || 45} ${L('минут','минут')}</span><span class="pill purple">${L('Индивидуально','Жеке жұмыс')}</span></div><h3>01. ${L('Задача','Тапсырма')}</h3><p>${d.practice}</p><h3>02. ${L('Порядок выполнения','Орындау реті')}</h3><ol><li>${L('Определите входные данные и ожидаемый результат.','Кіріс деректері мен күтілетін нәтижені анықтаңыз.')}</li><li>${L('Подготовьте решение, используя основные понятия темы.','Тақырыптың негізгі ұғымдарын пайдаланып, шешім дайындаңыз.')}</li><li>${L('Проверьте работу на примере и пограничном случае.','Жұмысты мысал мен шекті жағдайда тексеріңіз.')}</li><li>${L('Кратко объясните свой выбор.','Таңдауыңызды қысқаша түсіндіріңіз.')}</li></ol><h3>03. ${L('Критерии','Өлшемдер')}</h3><p>${d.criterion}</p><table><tr><th>${L('Критерий','Өлшем')}</th><th>${L('Баллы','Балл')}</th></tr><tr><td>${L('Корректность решения','Шешімнің дұрыстығы')}</td><td>50</td></tr><tr><td>${L('Проверка результата','Нәтижені тексеру')}</td><td>30</td></tr><tr><td>${L('Объяснение','Түсіндіру')}</td><td>20</td></tr></table><h3>04. ${L('Вопрос для обсуждения','Талқылау сұрағы')}</h3><p>${d.question}</p>`; }
function field(label,name,value,kind='input',choices=null,hint=''){
  const control=kind==='select'?`<select id="field-${name}" name="${name}">${choices.map(([v,text])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(text)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="field-${name}" name="${name}" maxlength="500">${e(value)}</textarea>`:`<input id="field-${name}" name="${name}" value="${e(value)}" ${kind==='number'?'type="number" min="4" max="180" step="1"':'type="text" maxlength="100"'} required>`;
  return `<div class="field"><label for="field-${name}">${label}</label>${control}${hint?`<p class="hint">${hint}</p>`:''}</div>`;
}
function renderGenerator(){
  const programme=state.page==='programmes'; const draft=state.formDrafts[state.page] || {};
  const types=programme?[['rp','РП'],['ktp',L('КТП','КТЖ')],['qmj','ҚМЖ']]:[['lesson',L('Занятие','Сабақ')],['assignment',L('Задание','Тапсырма')],['presentation',L('Слайды','Слайдтар')]];
  const active=programme?state.programmeType:state.materialType;
  return `${pageHead(pageTitle(state.page),L(programme?'От учебного модуля до понятного плана. В несколько шагов.':'Ваши идеи обретают форму. Начните с темы занятия.',programme?'Оқу модулінен түсінікті жоспарға дейін. Бірнеше қадамда.':'Идеяларыңызға пішін беріңіз. Сабақ тақырыбынан бастаңыз.'),`<span class="pill purple" style="padding:7px 11px">${icon('sparkles')}${L('Демо-генератор','Демо-генератор')}</span>`)}<div class="split-layout"><section class="panel form-panel"><h2>${L('Настроим результат','Нәтижені баптау')}</h2><p class="form-intro">${L('Несколько деталей, чтобы материал подошёл вашему занятию.','Материал сабағыңызға сай болуы үшін бірнеше мәлімет қосыңыз.')}</p><form id="generator-form"><div class="segmented">${types.map(([v,title])=>`<button type="button" data-action="generator-type" data-type="${v}" class="${active===v?'active':''}" aria-pressed="${active===v}">${title}</button>`).join('')}</div>${field(L(programme?'Модуль / дисциплина':'Тема материала',programme?'Модуль / пән':'Материал тақырыбы'),'topic',draft.topic || L(programme?'Основы программирования на Python':'Основы HTML и CSS',programme?'Python тілінде бағдарламалау негіздері':'HTML және CSS негіздері'),'input',null,L('Примеры: HTML и CSS, Python, SQL, кибербезопасность, ИИ. Другие темы показывают общий сценарий.','Мысалдар: HTML және CSS, Python, SQL, киберқауіпсіздік, ЖИ. Басқа тақырыптар жалпы сценарийді көрсетеді.'))}${field(L('Специальность','Мамандық'),'specialty',draft.specialty || 'software','select',[['software',L('06130100 · Программное обеспечение','06130100 · Бағдарламалық қамтамасыз ету')],['network',L('06120100 · Вычислительная техника','06120100 · Есептеу техникасы')],['digital',L('Информационные технологии','Ақпараттық технологиялар')]])}<div class="field-row">${field(L('Курс','Курс'),'course',draft.course || '2','select',[['1',L('1 курс','1 курс')],['2',L('2 курс','2 курс')],['3',L('3 курс','3 курс')]])}${programme&&active!=='qmj'?field(L('Объём, часов','Көлемі, сағат'),'hours',draft.hours || '72','number',null,'4–180'):field(L('Длительность','Ұзақтығы'),'minutes',draft.minutes || '90','select',[['45',L('45 минут','45 минут')],['90',L('90 минут','90 минут')]])}</div>${!programme?field(L('Результат обучения','Оқу нәтижесі'),'goal',draft.goal || L('Создать простую веб-страницу и объяснить роль HTML и CSS.','Қарапайым веб-бет жасап, HTML және CSS рөлін түсіндіру.'),'textarea'):''}<button type="submit" class="btn generate-button">${icon('sparkles')}${L(programme?'Сформировать программу':'Создать материал',programme?'Бағдарлама жасау':'Материал жасау')}</button><p class="demo-caption">${icon('help')}${L('Готовые учебные сценарии. ИИ не подключён; результат можно редактировать после экспорта.','Дайын оқу сценарийлері. ЖИ қосылмаған; экспорттан кейін нәтижені өңдеуге болады.')}</p></form></section><section class="panel preview-panel" id="preview-panel">${renderPreview(programme)}</section></div>`;
}
function renderPreview(programme){
  const preview=state.preview && state.preview.source===(programme?'programmes':'materials') ? state.preview : null;
  if(!preview)return `<div class="preview-toolbar"><div><h3>${L('Предпросмотр','Алдын ала қарау')}</h3><p>${L('Здесь появится ваш документ','Сіздің құжатыңыз осында көрсетіледі')}</p></div><span class="pill gray">${L('Ещё не создан','Әлі жасалмаған')}</span></div><div class="empty-preview">${lineArt(programme?1:0,'empty-art')}<h2>${L('Ваша следующая идея<br>уже почти здесь.','Келесі идеяңыз<br>осында пайда болады.')}</h2><p>${L('Заполните поля слева и запустите создание. Или посмотрите готовый пример.','Сол жақтағы өрістерді толтырып, жасауды бастаңыз. Немесе дайын мысалды көріңіз.')}</p>${btn(L('Показать пример','Мысалды көрсету'),'sample','secondary sample-button','eye')}</div>`;
  return `<div class="preview-toolbar"><div><h3>${L('Предпросмотр документа','Құжатты алдын ала қарау')}</h3><p>${L('Готово к сохранению','Сақтауға дайын')}</p></div><div class="toolbar-buttons">${btn(L('Сохранить','Сақтау'),'save-preview','secondary small','save')}${btn('DOCX','download-preview','small','download')}${btn('PDF','print-preview','secondary small','print')}</div></div><article class="document-preview">${preview.html}</article>`;
}
function generatorOptions(){
  const form=$('#generator-form');if(!form)return null;
  if(!form.reportValidity())return null;
  const values=Object.fromEntries(new FormData(form));if(!String(values.topic).trim()){toast(L('Введите тему.','Тақырыпты енгізіңіз.'));return null;}
  const option=form.elements.specialty.selectedOptions[0];values.specialty=option.text;values.topic=values.topic.trim();values.source=state.page;
  values.type=state.page==='programmes'?state.programmeType:state.materialType;
  state.formDrafts[state.page]=Object.fromEntries(new FormData(form));return values;
}
function makePreview(options){
  const kind=detectTopic(options.topic);
  let body=options.source==='programmes'?programmeContent(options):options.type==='presentation'?presentationContent(options.topic,kind,options):options.type==='assignment'?assignmentContent(options.topic,kind,options):lessonContent(options.topic,kind,options);
  if(options.type!=='lesson'){const metadata=`<div class="document-meta"><span class="pill purple">${e(options.course || '1–2')} ${L('курс','курс')}</span><span class="pill gray">${e(options.specialty)}</span></div>`;body=body.replace('</h2>','</h2>'+metadata);if(options.goal)body=body.replace('</h2>'+metadata,'</h2>'+metadata+`<h3>${L('Результат обучения','Оқу нәтижесі')}</h3><p>${e(options.goal)}</p>`);}
  const labels={rp:L('Рабочая программа','Оқу бағдарламасы'),ktp:L('Календарный план','Күнтізбелік жоспар'),qmj:L('Краткосрочный план','Қысқа мерзімді жоспар'),lesson:L('Учебное занятие','Оқу сабағы'),assignment:L('Практическое задание','Практикалық тапсырма'),presentation:L('План презентации','Презентация жоспары')};
  return {id:'doc-'+Date.now(),title:options.topic,subtitle:labels[options.type]+(options.source==='programmes'&&options.type!=='qmj'?' · '+options.hours+' '+L('часов','сағат'):''),type:options.type,topic:options.topic,html:body,date:new Date().toISOString(),style:'purple',cover:state.documents.length%4,source:options.source};
}
function generate(){ const options=generatorOptions();if(!options)return;cancelGeneration(false);state.generation={options,progress:0,timer:null};renderProgress();const steps=[14,33,55,78,95,100];let step=0;state.generation.timer=setInterval(()=>{if(!state.generation)return;state.generation.progress=steps[step++];renderProgress();if(step===steps.length){clearInterval(state.generation.timer);state.preview=makePreview(state.generation.options);state.generation=null;$('#preview-panel').innerHTML=renderPreview(state.page==='programmes');toast(L('Материал готов. Сохраните его в библиотеку или скачайте.','Материал дайын. Кітапханаға сақтаңыз немесе жүктеңіз.'));}},360); }
function renderProgress(){const generation=state.generation;if(!generation||!$('#preview-panel'))return;$('#preview-panel').innerHTML=`<div class="generation-state">${brandSymbol('generating-orbit')}<h2>${L('Собираем вашу идею','Идеяңызды дайындап жатырмыз')}</h2><p>${generation.progress<40?L('Подбираем учебный сценарий…','Оқу сценарийін таңдау…'):generation.progress<80?L('Формируем разделы документа…','Құжат бөлімдерін құру…'):L('Готовим результат к просмотру…','Нәтижені қарауға дайындау…')}</p><div class="generation-track" role="progressbar" aria-label="${L('Создание документа','Құжат жасау')}" aria-valuenow="${generation.progress}" aria-valuemin="0" aria-valuemax="100"><div class="generation-fill" style="width:${generation.progress}%"></div></div><span class="generation-percent">${generation.progress}%</span>${btn(L('Отменить','Болдырмау'),'cancel-generation','ghost small','close')}</div>`; }
function cancelGeneration(show=true){if(state.generation){clearInterval(state.generation.timer);state.generation=null;if($('#preview-panel'))$('#preview-panel').innerHTML=renderPreview(state.page==='programmes');if(show)toast(L('Создание отменено.','Жасау тоқтатылды.'));}}
function savePreview(){if(!state.preview)return;if(state.documents.some(d=>d.id===state.preview.id)){toast(L('Документ уже в библиотеке.','Құжат кітапханада бар.'));return;}state.documents.unshift({...state.preview});state.documents=state.documents.slice(0,60);persist();toast(L('Сохранено в библиотеку.','Кітапханаға сақталды.'));}
function showDocument(id){const doc=allDocuments().find(d=>d.id===id);if(!doc)return;state.modalDocument=doc;openModal(e(doc.title),L('Документ из вашей библиотеки','Кітапханадағы құжат'),`<article class="document-preview"><p class="print-caption hidden">ORBIT · ${e(doc.subtitle)}</p>${doc.html}</article>`,`${btn('DOCX','download-modal','small','download')}${btn(L('Печать / PDF','Басып шығару / PDF'),'print-modal','secondary small','print')}`,true);}

function renderLibrary(){
  const filters=[['all',L('Все материалы','Барлық материалдар')],['lesson',L('Занятия','Сабақтар')],['rp',L('Программы','Бағдарламалар')],['template',L('Шаблоны','Үлгілер')],['favorites',L('Избранное','Таңдаулылар')]];
  return `${pageHead(pageTitle('library'),L('Место, где ваши знания становятся общими.','Сіздің біліміңіз ортақ білімге айналатын орын.'),btn(L('Добавить материал','Материал қосу'),'upload-modal','','plus'))}<div class="library-toolbar"><div class="search-field">${icon('search')}<label class="sr-only" for="library-search">${L('Поиск материалов','Материал іздеу')}</label><input id="library-search" placeholder="${L('Найти в библиотеке…','Кітапханадан іздеу…')}" value="${e(state.search)}" maxlength="100"></div><div class="filter-tabs">${filters.map(([v,title])=>`<button data-action="library-filter" data-filter="${v}" class="${state.libraryFilter===v?'active':''}" aria-pressed="${state.libraryFilter===v}">${title}</button>`).join('')}</div></div><div class="library-grid" id="library-cards">${libraryCards()}</div><div class="upload-drop"><div><h3>${L('Ваши материалы тоже заслуживают места здесь.','Сіздің материалдарыңыз да осында болуға лайық.')}</h3><p>${L('Добавьте текстовый конспект или сохраните документ из генератора.','Мәтіндік конспект қосыңыз немесе генератор құжатын сақтаңыз.')}</p></div>${btn(L('Добавить конспект','Конспект қосу'),'upload-modal','secondary small','upload')}</div>`;
}
function libraryCards(){
  const filtered=allDocuments().filter(d=>{
    const matching=state.libraryFilter==='all'||(state.libraryFilter==='favorites'?state.favorites.includes(d.id):state.libraryFilter==='rp'?['rp','ktp','qmj'].includes(d.type):state.libraryFilter==='lesson'?['lesson','assignment','presentation','note'].includes(d.type):d.type===state.libraryFilter);
    return matching && `${d.title} ${d.subtitle || ''}`.toLowerCase().includes(state.search.toLowerCase());
  });
  if(!filtered.length)return `<div class="library-empty">${icon('search')}<p style="margin-top:13px">${L('Материалы не найдены. Попробуйте другой запрос или фильтр.','Материал табылмады. Басқа сұрау не сүзгіні қолданыңыз.')}</p></div>`;
  return filtered.map((d,i)=>`<article class="library-card"><div class="book-cover ${d.style==='green'?'':d.style || 'purple'}"><span class="book-no">ORBIT COLLECTION / ${String(i+1).padStart(2,'0')}</span><h3>${e(d.title)}</h3>${lineArt(d.cover || 0)}</div><div class="library-card-body"><span class="pill ${d.type==='template'?'orange':'gray'}">${e(d.subtitle || L('Учебный материал','Оқу материалы'))}</span><p>${L('Обновлено','Жаңартылған')} ${formatDate(d.date)}</p><div class="library-card-bottom"><button class="text-link" data-action="open-doc" data-id="${e(d.id)}">${L('Открыть материал','Материалды ашу')}${icon('arrow')}</button><button class="star-button ${state.favorites.includes(d.id)?'active':''}" data-action="favorite" data-id="${e(d.id)}" aria-label="${L('Добавить в избранное','Таңдаулыға қосу')}" aria-pressed="${state.favorites.includes(d.id)}">${state.favorites.includes(d.id)?'★':'☆'}</button></div></div></article>`).join('');
}
function uploadModal(){ openModal(L('Добавить в библиотеку','Кітапханаға қосу'),L('Сохраните собственный конспект','Өз конспектіңізді сақтаңыз'),`<p class="upload-note">${L('В демо можно добавить текстовый файл (.txt, .md) или вставить текст ниже. Материал сохранится в этом браузере.','Демода мәтіндік файл (.txt, .md) қосуға немесе төменге мәтін қоюға болады. Материал осы браузерде сақталады.')}</p><form id="upload-form">${field(L('Название','Атауы'),'title','')}${field(L('Текст материала','Материал мәтіні'),'text','','textarea')}<label class="btn secondary small" style="cursor:pointer">${icon('upload')}${L('Выбрать .txt / .md','Таңдау .txt / .md')}<input class="hidden" id="text-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label><div class="modal-footer"><button type="button" class="btn secondary small" data-action="close-modal">${L('Отмена','Болдырмау')}</button><button class="btn small" type="submit">${icon('save')}${L('Сохранить','Сақтау')}</button></div></form>`); $('#field-text')?.setAttribute('maxlength','30000'); }
function importText(form){const data=Object.fromEntries(new FormData(form));if(!data.title.trim()||!data.text.trim()){toast(L('Добавьте название и текст материала.','Материал атауы мен мәтінін қосыңыз.'));return;}const doc={id:'note-'+Date.now(),title:data.title.trim(),subtitle:L('Ваш конспект','Сіздің конспектіңіз'),type:'note',date:new Date().toISOString(),style:'green',cover:1,html:`<div class="doc-kicker">ORBIT / ${L('Конспект','Конспект')}</div><h2>${e(data.title)}</h2>${data.text.trim().split(/\n\s*\n/).map(p=>`<p style="white-space:pre-wrap">${e(p)}</p>`).join('')}`};state.documents.unshift(doc);state.documents=state.documents.slice(0,60);persist();closeModal();if(state.page==='library'){state.libraryFilter='all';state.search='';render();}toast(L('Конспект добавлен.','Конспект қосылды.'));}
function chatMessages(){ if(!Array.isArray(state.history[state.lang]))state.history[state.lang]=[];return state.history[state.lang]; }
function renderChat(){
  const tutor=state.page==='tutor';const suggestions=tutor?[L('Объясни SQL простыми словами','SQL-ді қарапайым тілмен түсіндір'),L('Помоги разобраться с CSS','CSS-ті түсінуге көмектес'),L('Дай упражнение на Python','Python тапсырмасын бер')]:[L('Как создать рабочую программу?','Оқу бағдарламасын қалай жасауға болады?'),L('Что умеет платформа?','Платформа не істей алады?'),L('Как скачать документ?','Құжатты қалай жүктеуге болады?')];
  return `${pageHead(pageTitle(state.page),L(tutor?'Сложные темы становятся понятными. Один вопрос за другим.':'Ваш помощник в пространстве колледжа. На русском и казахском.',tutor?'Күрделі тақырыптар түсінікті болады. Бір сұрақтан кейін екіншісі.':'Колледж кеңістігіндегі көмекшіңіз. Орысша және қазақша.'),btn(L('Новый диалог','Жаңа диалог'),'new-chat','secondary small','plus'))}<div class="chat-layout"><aside class="tutor-sidebar"><section class="panel tutor-topics"><h2>${L(tutor?'С чего начнём?':'Быстрые вопросы',tutor?'Неден бастаймыз?':'Жылдам сұрақтар')}</h2>${[[L('HTML и CSS','HTML және CSS'),'code'],[L('Базы данных и SQL','Деректер базасы және SQL'),'database'],[L('Основы Python','Python негіздері'),'file'],[L('Кибербезопасность','Киберқауіпсіздік'),'shield']].map(([topic,name])=>`<button class="topic-button" data-action="ask" data-question="${e(L('Объясни тему: ','Тақырыпты түсіндір: ')+topic)}">${icon(name)}${topic}</button>`).join('')}</section><section class="mentor-card"><span class="pill purple">${icon('sparkles')} ORBIT MENTOR</span><h3>${L('Можно спросить.<br>Можно ошибиться.','Сұрақ қоюға болады.<br>Қателесуге болады.')}</h3><p>${L('Хороший вопрос важнее быстрого ответа. Давайте разбираться вместе.','Жақсы сұрақ жылдам жауаптан маңызды. Бірге талдайық.')}</p></section></aside><section class="panel chat-panel"><header class="chat-header"><div class="ai-avatar">${icon('orbit')}</div><div><h3>Orbit ${tutor?'Mentor':'Assistant'}</h3><p>${L('Готовые объяснения и учебные примеры','Дайын түсіндірмелер және оқу мысалдары')}</p></div><span class="pill">${L('Демо','Демо')}</span></header><div class="chat-messages" id="chat-messages" role="log" aria-live="polite">${renderChatMessages()}</div><div class="chat-suggestions">${suggestions.map(q=>`<button data-action="ask" data-question="${e(q)}">${q}</button>`).join('')}</div><div class="chat-input-wrap"><form class="chat-form" id="chat-form"><label class="sr-only" for="chat-input">${L('Ваш вопрос','Сіздің сұрағыңыз')}</label><textarea id="chat-input" placeholder="${L('О чём хотите спросить?','Не туралы сұрағыңыз келеді?')}" maxlength="1000" required></textarea><button type="submit" aria-label="${L('Отправить вопрос','Сұрақ жіберу')}">${icon('send')}</button></form><p class="chat-input-caption">${L('Демонстрационные ответы из локальных сценариев · RU / ҚАЗ','Жергілікті сценарийлерден демонстрациялық жауаптар · RU / ҚАЗ')}</p></div></section></div>`;
}
function renderChatMessages(){const greetings=L('Привет! Я Orbit, ваш учебный помощник. Могу объяснить HTML и CSS, Python, SQL и основы кибербезопасности. Или подсказать, как пользоваться платформой. С чего начнём?','Сәлем! Мен Orbit, оқу көмекшісімін. HTML және CSS, Python, SQL және киберқауіпсіздік негіздерін түсіндіре аламын. Немесе платформаны қолдануды көрсетемін. Неден бастаймыз?');return [{role:'assistant',text:greetings},...chatMessages()].map(message=>`<div class="chat-message ${message.role==='user'?'user':''}"><div class="avatar ${message.role==='user'?'':'lime'}">${message.role==='user'?role().initials:'O'}</div><div><div class="bubble">${e(message.text)}</div><div class="message-caption">${message.role==='user'?e(currentName()):'ORBIT · '+L('учебный пример','оқу мысалы')}</div></div></div>`).join('');}
function answerQuestion(question){
  const q=question.toLowerCase();
  if(/программ[уыа]|бағдарлама|ктп|қмж|ктж/.test(q)&&!/python|пайтон|код/.test(q))return L('Откройте «Рабочие программы», выберите РП, КТП или ҚМЖ, укажите дисциплину и количество часов. Нажмите «Сформировать программу». Затем можно скачать DOCX или сохранить документ в библиотеку. В демо используются готовые структуры; утверждённые шаблоны колледжа пока не подключены.','«Оқу бағдарламалары» бөлімін ашып, оқу бағдарламасын, КТЖ немесе ҚМЖ таңдаңыз. Пәнді және сағат санын көрсетіп, «Бағдарлама жасау» батырмасын басыңыз. DOCX жүктеуге немесе кітапханаға сақтауға болады. Демода дайын құрылымдар қолданылады; колледждің бекітілген үлгілері әзірге қосылмаған.');
  if(/скач|сохран|экспорт|pdf|docx|жүкт|сақта/.test(q))return L('У созданного материала есть кнопки «Сохранить», «DOCX» и «PDF». «Сохранить» добавит его в библиотеку этого браузера. DOCX скачает редактируемый документ Word. PDF откроет окно печати: выберите «Сохранить как PDF». Аналитику можно выгрузить отдельно в Excel.','Жасалған материалда «Сақтау», «DOCX» және «PDF» батырмалары бар. «Сақтау» оны осы браузер кітапханасына қосады. DOCX өңдеуге болатын Word құжатын жүктейді. PDF басып шығару терезесін ашады: «PDF ретінде сақтау» таңдаңыз. Талдауды Excel форматына шығаруға болады.');
  if(/платформ|умеет|істей|orbit|возможност/.test(q))return L('Orbit объединяет материалы, рабочие программы, тьютора, тесты, аналитику, библиотеку и управление пользователями. Переключите роль вверху справа, чтобы показать разные сценарии. Это автономная демонстрация: помощник использует примеры, а результаты тестов сохраняются в текущем браузере.','Orbit материалдарды, оқу бағдарламаларын, тьюторды, тесттерді, талдауды, кітапхананы және пайдаланушыларды басқаруды біріктіреді. Әртүрлі сценарийді көрсету үшін жоғарғы оң жақтағы рөлді ауыстырыңыз. Бұл автономды демонстрация: көмекші мысалдарды қолданады, ал тест нәтижелері осы браузерде сақталады.');
  if(/привет|сәлем|здравств/.test(q))return L('Привет! Какую тему хотите разобрать? Например: «Объясни SQL», «Помоги с CSS» или «Дай упражнение на Python».','Сәлем! Қай тақырыпты талдаймыз? Мысалы: «SQL-ді түсіндір», «CSS-ке көмектес» немесе «Python тапсырмасын бер».');
  const kind=detectTopic(q);const known=/html|css|веб|sql|баз|деректер|python|пайтон|алгоритм|безопас|қауіп|кибер|интеллект|жасанды|\bai\b|\bии\b/.test(q);const d=topicData(kind);
  if(!known)return L('Для этого вопроса пока нет отдельного сценария. В полной версии здесь будет ответ языковой модели. В демонстрации могу помочь с HTML и CSS, SQL, Python, кибербезопасностью и работой платформы. Выберите тему слева или уточните вопрос.','Бұл сұраққа бөлек сценарий әзірге жоқ. Толық нұсқада тілдік модель жауап береді. Демода HTML және CSS, SQL, Python, киберқауіпсіздік және платформаны қолдану бойынша көмектесе аламын. Сол жақтан тақырып таңдаңыз немесе сұрақты нақтылаңыз.');
  if(/упражнен|задан|практик|тапсырма/.test(q))return `${L('Давайте попробуем на практике.','Практикада орындап көрейік.')}\n\n${d.practice}\n\n${L('Как проверить себя:','Өзін тексеру:')} ${d.criterion}`;
  return `${d.definition}\n\n${L('Небольшой пример:','Шағын мысал:')}\n${d.example}\n\n${L('Вопрос для размышления:','Ойлануға сұрақ:')} ${d.question}`;
}
function askQuestion(question){
  if(state.chatBusy)return;const q=String(question || '').trim().slice(0,1000);if(!q)return;const lang=state.lang;
  chatMessages().push({role:'user',text:q});chatMessages().splice(0,Math.max(0,chatMessages().length-40));state.chatBusy=true;
  const messages=$('#chat-messages');if(messages){messages.innerHTML=renderChatMessages()+`<div class="chat-message" id="typing"><div class="avatar lime">O</div><div class="bubble"><div class="typing"><span></span><span></span><span></span></div></div></div>`;messages.scrollTop=messages.scrollHeight;}
  if($('#chat-input'))$('#chat-input').value='';const response=answerQuestion(q);
  state.chatTimer=setTimeout(()=>{state.history[lang].push({role:'assistant',text:response});state.chatBusy=false;persist();if($('#chat-messages')&&state.lang===lang){$('#chat-messages').innerHTML=renderChatMessages();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}},650);
}

function quizBank(key){
  const definitions={
    web:[
      [L('Для чего используется HTML?','HTML не үшін қолданылады?'),[L('Для структуры веб-страницы','Веб-бет құрылымы үшін'),L('Для хранения паролей','Құпиясөз сақтау үшін'),L('Для настройки сервера','Серверді баптау үшін'),L('Для создания базы данных','Деректер базасын жасау үшін')],0,L('HTML описывает структуру: заголовки, абзацы, ссылки и другие элементы.','HTML құрылымды сипаттайды: тақырыптар, абзацтар, сілтемелер және басқа элементтер.')],
      [L('Какое свойство задаёт внутренний отступ?','Ішкі бос орынды қай қасиет береді?'),['margin','padding','border','display'],1,L('Padding — отступ внутри границы элемента; margin — снаружи.','Padding — элемент шекарасының ішіндегі, margin — сыртындағы бос орын.')],
      [L('Какой тег обозначает главный заголовок?','Негізгі тақырыпты қай тег белгілейді?'),['<p>','<div>','<h1>','<span>'],2,L('H1 используют для главного заголовка страницы.','H1 беттің негізгі тақырыбы үшін қолданылады.')],
      [L('Как включить CSS Grid?','CSS Grid қалай қосылады?'),['position: grid','layout: grid','grid: enabled','display: grid'],3,L('Свойство display: grid превращает элемент в Grid-контейнер.','Display: grid қасиеті элементті Grid-контейнерге айналдырады.')],
      [L('Что помогает адаптировать страницу к экрану?','Бетті экранға бейімдеуге не көмектеседі?'),[L('Медиазапросы CSS','CSS медиасұраулары'),L('Больше тегов br','Көбірек br тегтері'),L('Фиксированная ширина 1920px','1920px тұрақты ен'),L('Отключение CSS','CSS-ті өшіру')],0,L('Медиазапросы позволяют менять стили в зависимости от ширины экрана.','Медиасұраулар экран еніне қарай стильдерді өзгертеді.')]
    ],
    sql:[
      [L('Какая команда получает данные из таблицы?','Кестеден деректерді қай команда алады?'),['DELETE','INSERT','SELECT','UPDATE'],2,L('SELECT выбирает данные, а FROM задаёт таблицу.','SELECT деректерді таңдайды, FROM кестені көрсетеді.')],
      [L('Как выбрать строки с баллом выше 80?','Балы 80-нен жоғары жолдарды қалай таңдаймыз?'),['ORDER BY score > 80','WHERE score > 80','GROUP score > 80','FROM score > 80'],1,L('WHERE задаёт условие фильтрации строк.','WHERE жолдарды сүзу шартын береді.')],
      [L('Что делает первичный ключ?','Бастапқы кілт не істейді?'),[L('Уникально определяет строку','Жолды бірегей анықтайды'),L('Шифрует таблицу','Кестені шифрлайды'),L('Сортирует имена','Аттарды сұрыптайды'),L('Удаляет дубликаты автоматически','Қайталануларды өзі жояды')],0,L('PRIMARY KEY требует уникальное непустое значение для каждой строки.','PRIMARY KEY әр жолға бірегей бос емес мәнді талап етеді.')],
      [L('Как сортировать score по убыванию?','Score мәнін кему ретімен қалай сұрыптаймыз?'),['SORT score DOWN','WHERE score DESC','ORDER BY score ASC','ORDER BY score DESC'],3,L('DESC задаёт убывание, ASC — возрастание.','DESC — кему реті, ASC — өсу реті.')],
      [L('Что связывает данные двух таблиц?','Екі кесте деректерін не байланыстырады?'),[L('Цвет столбца','Баған түсі'),'FOREIGN KEY','ORDER BY','LIMIT'],1,L('Внешний ключ ссылается на ключ другой таблицы и поддерживает связь.','Сыртқы кілт басқа кестенің кілтіне сілтеп, байланысты сақтайды.')]
    ],
    python:[
      [L('Какой тип у значения True?','True мәнінің түрі қандай?'),['int','str','float','bool'],3,L('True и False — логические значения типа bool.','True және False — bool түріндегі логикалық мәндер.')],
      [L('Что вернёт len([1, 2, 3])?','Len([1, 2, 3]) не қайтарады?'),['2','3','6','[1, 2, 3]'],1,L('Len возвращает количество элементов: здесь их три.','Len элементтер санын қайтарады: мұнда үшеу.')],
      [L('Как начать объявление функции?','Функцияны жариялау қалай басталады?'),['function name():','func name():','def name():','define name():'],2,L('В Python функции объявляют ключевым словом def.','Python функциялары def кілт сөзімен жарияланады.')],
      [L('Что делает return?','Return не істейді?'),[L('Возвращает результат из функции','Функция нәтижесін қайтарады'),L('Всегда печатает текст','Әрдайым мәтін шығарады'),L('Запускает цикл','Циклді іске қосады'),L('Импортирует модуль','Модульді импорттайды')],0,L('Return завершает функцию и передаёт значение вызывающему коду.','Return функцияны аяқтап, мәнді шақырған кодқа береді.')],
      [L('Какой цикл удобен для перебора списка?','Тізімді қарауға қай цикл ыңғайлы?'),['if','for','try','def'],1,L('For последовательно проходит по элементам списка или другого итерируемого объекта.','For тізім немесе басқа қайталанатын объект элементтерін ретімен қарайды.')]
    ]
  };
  return (definitions[key] || definitions.web).map(([question,answers,correct,explanation])=>({question,answers,correct,explanation}));
}
function quizTitle(key){return key==='sql'?L('Базы данных и SQL','Деректер базасы және SQL'):key==='python'?L('Основы Python','Python негіздері'):L('HTML и CSS','HTML және CSS');}
function renderTests(){
  if(state.quizResult)return renderQuizResult();if(state.quiz)return renderQuiz();
  return `${pageHead(pageTitle('tests'),L('Проверьте знания. Найдите точки роста. Сделайте следующий шаг.','Біліміңізді тексеріңіз. Даму мүмкіндігін табыңыз. Келесі қадамды жасаңыз.'),(state.role==='student'?'':btn(L('Создать тест','Тест жасау'),'create-test','secondary','plus')))}<div class="tip-banner">${icon('sparkles')}<span>${L('Каждый тест — 5 вопросов с разбором ответов. Результат появится в аналитике.','Әр тестте 5 сұрақ және жауаптардың талдауы бар. Нәтиже талдау бөлімінде көрсетіледі.')}</span></div><div class="test-grid">${['web','sql','python'].map((key,i)=>`<section class="test-card">${lineArt(i,'test-art')}<h2>${quizTitle(key)}</h2><p>${L(i===0?'Структура, стили и адаптивность':i===1?'Запросы, таблицы и связи':'Переменные, функции и циклы',i===0?'Құрылым, стильдер және бейімделу':i===1?'Сұраулар, кестелер және байланыстар':'Айнымалылар, функциялар және циклдер')}</p><div class="test-meta"><span>${icon('checklist')} 5 ${L('вопросов','сұрақ')}</span><span>${icon('clock')} ~ 3 ${L('мин','мин')}</span></div>${btn(L('Начать тест','Тестті бастау'),'start-test',i===1?'dark':'','arrow',`data-key="${key}"`)}</section>`).join('')}</div>${state.results.length?`<div class="section-head"><h2>${L('Ваши последние результаты','Соңғы нәтижелеріңіз')}</h2><span class="pill gray">${L('Сохранены в браузере','Браузерде сақталған')}</span></div><div class="table-panel"><table class="data-table"><thead><tr><th>${L('Тест','Тест')}</th><th>${L('Результат','Нәтиже')}</th><th>${L('Дата','Күні')}</th></tr></thead><tbody>${state.results.slice(-5).reverse().map(r=>`<tr><td>${e(r.title)}</td><td><span class="pill ${r.score>=60?'':'orange'}">${r.score}% · ${r.correct}/5</span></td><td class="dim">${formatDate(r.date)}</td></tr>`).join('')}</tbody></table></div>`:''}`;
}
function startTest(key){state.quiz={key,title:quizTitle(key),questions:quizBank(key),language:state.lang};state.quizIndex=0;state.quizAnswers=[];state.quizResult=null;closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
function renderQuiz(){const q=state.quiz.questions[state.quizIndex];return `${pageHead(state.quiz.title,L('Выберите один ответ. Вернуться к предыдущему вопросу можно в любой момент.','Бір жауапты таңдаңыз. Алдыңғы сұраққа кез келген уақытта оралуға болады.'))}<section class="panel quiz-panel"><div class="quiz-top"><span>${L('Вопрос','Сұрақ')} ${state.quizIndex+1} / ${state.quiz.questions.length}</span><button class="text-link" data-action="exit-quiz">${L('Завершить позже','Кейін аяқтау')}${icon('close')}</button></div><div class="quiz-track"><div style="width:${(state.quizIndex+1)/state.quiz.questions.length*100}%"></div></div><h2>${e(q.question)}</h2>${q.answers.map((answer,i)=>`<button class="answer-option ${state.quizAnswers[state.quizIndex]===i?'selected':''}" data-action="answer" data-answer="${i}" aria-pressed="${state.quizAnswers[state.quizIndex]===i}"><span class="answer-letter">${String.fromCharCode(65+i)}</span>${e(answer)}</button>`).join('')}<div class="quiz-actions"><button class="btn secondary" data-action="quiz-back" ${state.quizIndex===0?'disabled':''}>${icon('back')}${L('Назад','Артқа')}</button><button class="btn" data-action="quiz-next" ${state.quizAnswers[state.quizIndex]===undefined?'disabled':''}>${state.quizIndex===4?L('Узнать результат','Нәтижені көру'):L('Следующий вопрос','Келесі сұрақ')}${icon('arrow')}</button></div></section>`;}
function finishQuiz(){const correct=state.quiz.questions.reduce((total,q,i)=>total+Number(q.correct===state.quizAnswers[i]),0);const result={title:state.quiz.title,key:state.quiz.key,correct,score:correct/5*100,date:new Date().toISOString(),user:currentName(),role:state.role};state.results.push(result);state.results=state.results.slice(-30);persist();state.quizResult={...result,questions:state.quiz.questions,answers:[...state.quizAnswers]};state.quiz=null;render();window.scrollTo({top:0,behavior:'instant'});}
function renderQuizResult(){const r=state.quizResult;const circumference=2*Math.PI*78;return `${pageHead(L('Ваш результат','Сіздің нәтижеңіз'),L('Знания — это путь. Теперь понятно, куда двигаться дальше.','Білім — жол. Енді қай бағытта жүру керектігі түсінікті.'))}<section class="panel quiz-panel"><div class="quiz-result"><div class="result-ring"><svg viewBox="0 0 190 190" fill="none" aria-hidden="true"><circle cx="95" cy="95" r="78" stroke="#eef2e3" stroke-width="10"/><circle cx="95" cy="95" r="78" stroke="#aecb80" stroke-width="10" stroke-linecap="round" stroke-dasharray="${circumference}" stroke-dashoffset="${circumference*(1-r.score/100)}"/></svg><strong>${r.score}%</strong><span>${r.correct} / 5 ${L('верных ответов','дұрыс жауап')}</span></div><div class="result-copy"><span class="pill">${L('Результат сохранён','Нәтиже сақталды')}</span><h2 style="margin-top:15px">${L(r.score===100?'Отличная работа!':r.score>=60?'Уверенный шаг вперёд.':'Есть с чего начать.',r.score===100?'Керемет жұмыс!':r.score>=60?'Алға сенімді қадам.':'Бастауға негіз бар.')}</h2><p>${L(r.score>=60?'Посмотрите разбор, чтобы закрепить знания.':'Разберите ошибки и попробуйте ещё раз. Учиться — значит пробовать.',r.score>=60?'Білімді бекіту үшін талдауды қараңыз.':'Қателерді талдап, қайта көріңіз. Оқу — әрекет ету.')}</p>${btn(L('Ещё один тест','Тағы бір тест'),'back-tests','secondary small','reset')}</div></div><h3 style="margin-bottom:9px">${L('Разберём ответы','Жауаптарды талдау')}</h3>${r.questions.map((q,i)=>`<div class="review-item ${q.correct===r.answers[i]?'':'wrong'}"><h3>${icon(q.correct===r.answers[i]?'check':'close')}${i+1}. ${e(q.question)}</h3>${q.correct!==r.answers[i]?`<p>${L('Ваш ответ','Сіздің жауабыңыз')}: ${e(q.answers[r.answers[i]])}</p>`:''}<p>${L('Верно','Дұрыс')}: ${e(q.answers[q.correct])}. ${e(q.explanation)}</p></div>`).join('')}</section>`;}
function createTestModal(){openModal(L('Создать учебный тест','Оқу тестін жасау'),L('Выберите один из готовых наборов вопросов','Дайын сұрақтар жиынтығын таңдаңыз'),`<p class="upload-note">${L('В полной версии вопросы предложит ИИ. Сейчас доступны три сценария, которые можно пройти и разобрать.','Толық нұсқада сұрақтарды ЖИ ұсынады. Қазір өтуге және талдауға болатын үш сценарий бар.')}</p><form id="test-create-form">${field(L('Тема','Тақырып'),'quizTopic','web','select',['web','sql','python'].map(key=>[key,quizTitle(key)]))}<div class="modal-footer"><button type="submit" class="btn">${icon('sparkles')}${L('Создать и пройти','Жасау және өту')}</button></div></form>`);}

const sampleStudents=[
  {name:'Данияр Омаров',group:'ПО-24-1',score:84,attendance:96,tests:4},
  {name:'Аружан Садыкова',group:'ПО-23-1',score:95,attendance:100,tests:5},
  {name:'Тимур Волков',group:'ПО-23-1',score:78,attendance:92,tests:4},
  {name:'Айша Ермекова',group:'ПО-24-1',score:92,attendance:100,tests:5},
  {name:'Никита Петров',group:'ПО-23-1',score:67,attendance:84,tests:3},
  {name:'Алина Бекова',group:'ПО-24-1',score:88,attendance:96,tests:5},
  {name:'Санжар Мусин',group:'ПО-23-1',score:59,attendance:76,tests:2},
  {name:'Камила Исаева',group:'ПО-24-1',score:91,attendance:100,tests:5}
];
function studentsData(){return sampleStudents.map(s=>{if(s.name==='Данияр Омаров'){const results=state.results.filter(r=>r.role==='student');if(results.length)return {...s,score:results.at(-1).score,tests:s.tests+results.length};}return {...s};}).filter(s=>state.analyticsGroup==='all'||s.group===state.analyticsGroup);}
function renderAnalytics(){
  const students=studentsData(),average=Math.round(students.reduce((n,s)=>n+s.score,0)/students.length),attendance=Math.round(students.reduce((n,s)=>n+s.attendance,0)/students.length),passed=students.filter(s=>s.score>=60).length;
  const controls=`<div class="analytics-controls"><label class="sr-only" for="analytics-group">${L('Группа','Топ')}</label><select id="analytics-group"><option value="all">${L('Все группы','Барлық топтар')}</option>${['ПО-23-1','ПО-24-1'].map(g=>`<option value="${g}" ${state.analyticsGroup===g?'selected':''}>${g}</option>`).join('')}</select><label class="sr-only" for="analytics-period">${L('Период','Кезең')}</label><select id="analytics-period"><option value="month" ${state.analyticsPeriod==='month'?'selected':''}>${L('Этот месяц','Осы ай')}</option><option value="week" ${state.analyticsPeriod==='week'?'selected':''}>${L('Эта неделя','Осы апта')}</option></select>${btn(L('Отчёт','Есеп'),'export-analytics','secondary small','download')}</div>`;
  const week=state.analyticsPeriod==='week',labels=week?L(['Пн','Вт','Ср','Чт','Пт'],['Дс','Сс','Ср','Бс','Жм']):L(['1 нед.','2 нед.','3 нед.','4 нед.'],['1 апта','2 апта','3 апта','4 апта']);
  const chartValues=week?[average-7,average-3,average,average+3,average+5]:[average-11,average-7,average-2,average];
  const high=students.filter(s=>s.score>=85).length,normal=students.filter(s=>s.score>=60&&s.score<85).length,low=students.length-high-normal;const c=2*Math.PI*65;
  return `${pageHead(pageTitle('analytics'),L('За цифрами — люди. Помогайте каждому двигаться вперёд.','Сандардың артында адамдар бар. Әрқайсысына алға жүруге көмектесіңіз.'),controls)}<div class="metric-grid">${metric(L('Студентов в выборке','Таңдаудағы студенттер'),students.length,L('Учебные данные','Оқу деректері'))}${metric(L('Средний результат','Орташа нәтиже'),average+'%',L('По выбранной группе','Таңдалған топ бойынша'))}${metric(L('Посещаемость','Қатысу'),attendance+'%',L('По выбранной группе','Таңдалған топ бойынша'))}${metric(L('Порог 60% пройден','60% шегінен өткен'),Math.round(passed/students.length*100)+'%',passed+' / '+students.length+' '+L('студентов','студент'))}</div><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>${L('Траектория обучения','Оқу траекториясы')}</h2><p>${L('Иллюстрация динамики для выбранной группы','Таңдалған топтың динамика үлгісі')}</p></div><span class="pill gray">${L('Демо','Демо')}</span></div><div class="chart-wrap"><div class="chart-grid">${[100,75,50,25,0].map(n=>`<div class="chart-line"><span>${n}%</span></div>`).join('')}</div><div class="bar-chart">${labels.map((label,i)=>`<div class="bar-group"><div class="bar-pair"><div class="bar" style="height:${Math.max(0,Math.min(100,chartValues[i]))}%"><span class="bar-value">${chartValues[i]}%</span></div><div class="bar alt" style="height:${Math.min(100,attendance-6+i*2)}%"><span class="bar-value">${Math.min(100,attendance-6+i*2)}%</span></div></div><span class="bar-label">${label}</span></div>`).join('')}</div></div><div class="chart-legend"><span><i></i>${L('Результаты','Нәтижелер')}</span><span><i class="alt"></i>${L('Посещаемость','Қатысу')}</span></div></section><section class="panel"><div class="panel-head"><h2>${L('Уровень освоения','Игеру деңгейі')}</h2><span class="pill gray">${students.length} ${L('чел.','адам')}</span></div><div class="donut-wrap"><svg viewBox="0 0 170 170" fill="none" aria-hidden="true"><circle cx="85" cy="85" r="65" stroke="#f1f4e9" stroke-width="16"/><circle cx="85" cy="85" r="65" stroke="#b6ca8b" stroke-width="16" stroke-dasharray="${c*high/students.length} ${c}"/><circle cx="85" cy="85" r="65" stroke="#afb6dd" stroke-width="16" stroke-dasharray="${c*normal/students.length} ${c}" stroke-dashoffset="${-c*high/students.length}"/><circle cx="85" cy="85" r="65" stroke="#e4b99b" stroke-width="16" stroke-dasharray="${c*low/students.length} ${c}" stroke-dashoffset="${-c*(high+normal)/students.length}"/></svg><div class="donut-text"><strong>${average}%</strong><span>${L('средний результат','орташа нәтиже')}</span></div></div><div class="donut-legend"><div><i></i>${L('Уверенно · 85–100%','Сенімді · 85–100%')}<strong>${high}</strong></div><div><i style="background:#afb6dd"></i>${L('В процессе · 60–84%','Процесте · 60–84%')}<strong>${normal}</strong></div><div><i style="background:#e4b99b"></i>${L('Нужна поддержка · <60%','Көмек қажет · <60%')}<strong>${low}</strong></div></div></section></div><div class="section-head"><h2>${L('Прогресс студентов','Студенттердің жетістігі')}</h2><span class="pill gray">${L('Синтетические учебные данные','Оқу деректерінің үлгісі')}</span></div><div class="table-panel admin-table"><table class="data-table"><thead><tr><th>${L('Студент','Студент')}</th><th>${L('Группа','Топ')}</th><th>${L('Результат','Нәтиже')}</th><th class="mobile-hide">${L('Посещаемость','Қатысу')}</th><th>${L('Рекомендация','Ұсыныс')}</th></tr></thead><tbody>${students.map((s,i)=>`<tr><td><div class="user-cell"><span class="avatar ${i%2?'lime':'blue'}">${s.name.split(' ').map(n=>n[0]).join('')}</span><span>${s.name}</span></div></td><td class="dim">${s.group}</td><td><div class="student-progress"><span>${s.score}%</span><div class="progress-track"><div class="progress-fill" style="width:${s.score}%;background:${s.score<60?'#ddb79c':'#bdce91'}"></div></div></div></td><td class="dim mobile-hide">${s.attendance}%</td><td><span class="pill ${s.score<60?'orange':s.score<85?'purple':''}">${L(s.score<60?'Повторить основы':s.score<85?'Больше практики':'Следующий уровень',s.score<60?'Негіздерді қайталау':s.score<85?'Көбірек практика':'Келесі деңгей')}</span></td></tr>`).join('')}</tbody></table></div>${state.results.length?`<div class="section-head"><h2>${L('Результаты этого показа','Осы көрсетілімнің нәтижелері')}</h2></div><div class="table-panel"><table class="data-table"><thead><tr><th>${L('Участник','Қатысушы')}</th><th>${L('Тест','Тест')}</th><th>${L('Результат','Нәтиже')}</th></tr></thead><tbody>${state.results.slice(-5).reverse().map(r=>`<tr><td>${e(r.user)}</td><td>${e(r.title)}</td><td><span class="pill">${r.score}%</span></td></tr>`).join('')}</tbody></table></div>`:''}`;
}
function metric(label,value,note){return `<section class="metric-card"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><small>${note}</small></section>`;}
function getUsers(){if(!state.users)state.users=[{id:'u1',name:'Алина Серикова',email:'a.serikova@college.example',role:'teacher',active:true},{id:'u2',name:'Данияр Омаров',email:'d.omarov@college.example',role:'student',active:true},{id:'u3',name:'Айгуль Нурланова',email:'a.nurlanova@college.example',role:'methodist',active:true},{id:'u4',name:'Ерлан Ахметов',email:'e.akhmetov@college.example',role:'leadership',active:true},{id:'u5',name:'Максим Ким',email:'m.kim@college.example',role:'admin',active:true},{id:'u6',name:'Анна Ли',email:'a.li@college.example',role:'teacher',active:false}];return state.users;}
function renderAdmin(){const users=getUsers();return `${pageHead(pageTitle('admin'),L('Люди, роли и настройки вашего пространства.','Кеңістігіңіздің адамдары, рөлдері және баптаулары.'),btn(L('Добавить пользователя','Пайдаланушы қосу'),'add-user','','plus'))}<div class="admin-summary"><span class="pill gray">${users.length} ${L('пользователей','пайдаланушы')}</span><span class="pill">${users.filter(u=>u.active).length} ${L('активных','белсенді')}</span><span class="pill purple">5 ${L('ролей доступа','қол жеткізу рөлі')}</span></div><div class="table-panel admin-table"><table class="data-table"><thead><tr><th>${L('Пользователь','Пайдаланушы')}</th><th>${L('Роль','Рөл')}</th><th>${L('Статус','Күйі')}</th><th>${L('Действия','Әрекеттер')}</th></tr></thead><tbody>${users.map((u,i)=>`<tr><td><div class="user-cell"><span class="avatar ${i%2?'lime':''}">${e(u.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</span><div>${e(u.name)}<small>${e(u.email)}</small></div></div></td><td><span class="pill purple">${roles[u.role]?.label[state.lang==='ru'?0:1] || L('Студент','Студент')}</span></td><td><span class="pill ${u.active?'':'gray'}">${L(u.active?'Активен':'Приостановлен',u.active?'Белсенді':'Тоқтатылған')}</span></td><td><div class="user-actions"><button class="row-action" data-action="edit-user" data-id="${e(u.id)}" aria-label="${L('Редактировать','Өңдеу')} ${e(u.name)}">${icon('edit')}</button><button class="row-action" data-action="toggle-user" data-id="${e(u.id)}" aria-label="${L(u.active?'Приостановить':'Активировать',u.active?'Тоқтату':'Белсендіру')} ${e(u.name)}">${icon(u.active?'shield':'check')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>${L('Настройки пространства','Кеңістік баптаулары')}</h2><p>${L('Демонстрация будущих настроек','Болашақ баптаулар демонстрациясы')}</p></div>${icon('shield')}</div><div class="settings-row"><div>${L('Журнал действий','Әрекеттер журналы')}<small>${L('Сценарий учёта изменений пользователей','Пайдаланушы өзгерістерін есепке алу сценарийі')}</small></div><button class="switch ${state.settings.audit?'on':''}" data-action="setting" data-setting="audit" role="switch" aria-checked="${state.settings.audit}" aria-label="${L('Журнал действий','Әрекеттер журналы')}"></button></div><div class="settings-row"><div>${L('Проверка шаблонов','Үлгілерді тексеру')}<small>${L('Сценарий контроля обязательных разделов','Міндетті бөлімдерді бақылау сценарийі')}</small></div><button class="switch ${state.settings.template?'on':''}" data-action="setting" data-setting="template" role="switch" aria-checked="${state.settings.template}" aria-label="${L('Проверка шаблонов','Үлгілерді тексеру')}"></button></div><p class="demo-caption">${icon('help')}${L('Настройки показывают будущий интерфейс. Серверная авторизация и проверки безопасности в демо отсутствуют.','Баптаулар болашақ интерфейсті көрсетеді. Демода серверлік авторизация мен қауіпсіздік тексерулері жоқ.')}</p></section><section class="panel"><div class="panel-head"><div><h2>${L('Демонстрационные данные','Демонстрациялық деректер')}</h2><p>${L('Подготовьте пространство к следующему показу','Кеңістікті келесі көрсетілімге дайындаңыз')}</p></div>${icon('database')}</div><p class="upload-note">${L('Документы, результаты тестов, диалоги и пользователи сохраняются в текущем браузере. При переносе HTML на другой компьютер открывается исходный набор примеров.','Құжаттар, тест нәтижелері, диалогтар және пайдаланушылар осы браузерде сақталады. HTML басқа компьютерге көшірілгенде бастапқы мысалдар жиынтығы ашылады.')}</p><div style="display:flex;flex-wrap:wrap;gap:9px">${btn(L('Скачать резервную копию','Сақтық көшірмені жүктеу'),'backup','secondary small','download')}${btn(L('Сбросить демо','Демоны қалпына келтіру'),'reset-modal','danger small','reset')}</div><p class="demo-caption">${icon('leaf')}${L('Демо работает автономно. Данные не отправляются в сеть.','Демо автономды жұмыс істейді. Деректер желіге жіберілмейді.')}</p></section></div>`;}
function userModal(id){const user=id?getUsers().find(u=>u.id===id):null;if(id&&!user)return;openModal(L(user?'Редактировать пользователя':'Новый пользователь',user?'Пайдаланушыны өңдеу':'Жаңа пайдаланушы'),L('Учебная запись для демонстрации управления','Басқаруды көрсетуге арналған оқу жазбасы'),`<form id="user-form"><input type="hidden" name="id" value="${e(id || '')}">${field(L('Имя и фамилия','Аты-жөні'),'name',user?.name || '')}<div class="field"><label for="user-email">Email</label><input id="user-email" type="email" name="email" value="${e(user?.email || '')}" required maxlength="120" placeholder="name@college.example"></div>${field(L('Роль','Рөл'),'userRole',user?.role || 'student','select',Object.entries(roles).map(([key,r])=>[key,r.label[state.lang==='ru'?0:1]]))}<div class="modal-footer"><button class="btn secondary small" type="button" data-action="close-modal">${L('Отмена','Болдырмау')}</button><button class="btn small" type="submit">${icon('save')}${L('Сохранить','Сақтау')}</button></div></form>`);}
function saveUser(form){const data=Object.fromEntries(new FormData(form)),users=getUsers();if(!data.name.trim()){toast(L('Введите имя.','Атын енгізіңіз.'));return;}if(users.some(u=>u.email.toLowerCase()===data.email.trim().toLowerCase()&&u.id!==data.id)){toast(L('Этот email уже есть в списке.','Бұл email тізімде бар.'));return;}const found=users.find(u=>u.id===data.id);if(found)Object.assign(found,{name:data.name.trim(),email:data.email.trim(),role:data.userRole});else users.push({id:'u'+Date.now(),name:data.name.trim(),email:data.email.trim(),role:data.userRole,active:true});persist();closeModal();render();toast(L('Пользователь сохранён.','Пайдаланушы сақталды.'));}

const utf8=new TextEncoder();
const crcTable=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function zipFiles(files){
  const locals=[],centrals=[];let offset=0;
  for(const [name,text] of Object.entries(files)){
    const nameBytes=utf8.encode(name),data=utf8.encode(text),crc=crc32(data),local=new Uint8Array(30+nameBytes.length),lv=new DataView(local.buffer);
    lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(12,0x21,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,nameBytes.length,true);local.set(nameBytes,30);locals.push(local,data);
    const central=new Uint8Array(46+nameBytes.length),cv=new DataView(central.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,0x21,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,nameBytes.length,true);cv.setUint32(42,offset,true);central.set(nameBytes,46);centrals.push(central);offset+=local.length+data.length;
  }
  const size=centrals.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,centrals.length,true);ev.setUint16(10,centrals.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...locals,...centrals,end],{type:'application/zip'});
}
const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'');
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function docxParagraph(text,style='Normal'){return `<w:p><w:pPr><w:pStyle w:val="${style}"/></w:pPr><w:r><w:t xml:space="preserve">${String(text).split('\n').map(line=>xml(line)).join('</w:t><w:br/><w:t xml:space="preserve">')}</w:t></w:r></w:p>`;}
function makeDocx(doc){
  const container=document.createElement('div');container.innerHTML=doc.html;container.querySelectorAll('.doc-tip').forEach(n=>n.remove());let body='';
  const walk=node=>{
    if(node.nodeType!==1)return;
    const tag=node.tagName.toLowerCase();
    if(tag==='h2'){body+=docxParagraph(node.textContent,'Title');return;}
    if(tag==='h3'){body+=docxParagraph(node.textContent,'Heading1');return;}
    if(tag==='p'||tag==='li'){body+=docxParagraph((tag==='li'?'• ':'')+node.textContent);return;}
    if(tag==='table'){
      const rows=[...node.rows];const colCount=Math.max(...rows.map(row=>[...row.cells].reduce((n,c)=>n+(c.colSpan || 1),0)));const colWidth=Math.floor(9300/colCount);
      body+=`<w:tbl><w:tblPr><w:tblW w:w="9300" w:type="dxa"/><w:tblBorders>${['top','left','bottom','right','insideH','insideV'].map(side=>`<w:${side} w:val="single" w:sz="4" w:color="D9D9D9"/>`).join('')}</w:tblBorders><w:tblCellMar><w:top w:w="90" w:type="dxa"/><w:left w:w="100" w:type="dxa"/><w:bottom w:w="90" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${Array.from({length:colCount},()=>`<w:gridCol w:w="${colWidth}"/>`).join('')}</w:tblGrid>${rows.map((row,i)=>`<w:tr>${i===0?'<w:trPr><w:tblHeader/></w:trPr>':''}${[...row.cells].map(cell=>`<w:tc><w:tcPr><w:tcW w:w="${colWidth*(cell.colSpan||1)}" w:type="dxa"/>${cell.colSpan>1?`<w:gridSpan w:val="${cell.colSpan}"/>`:''}${cell.tagName==='TH'?'<w:shd w:fill="E9EDDE"/>':''}<w:vAlign w:val="center"/></w:tcPr>${docxParagraph(cell.textContent)}</w:tc>`).join('')}</w:tr>`).join('')}</w:tbl>`;return;
    }
    if(node.classList.contains('doc-kicker')||node.classList.contains('document-meta')){body+=docxParagraph(node.classList.contains('document-meta')?[...node.children].map(n=>n.textContent).join(' · '):node.textContent,'Subtitle');return;}
    for(const child of node.children)walk(child);
  };for(const child of container.children)walk(child);
  const files={
    '[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>',
    '_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>',
    'word/_rels/document.xml.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
    'word/document.xml':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1200" w:right="1300" w:bottom="1200" w:left="1300"/></w:sectPr></w:body></w:document>`,
    'word/styles.xml':'<?xml version="1.0" encoding="UTF-8"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:cs="Calibri"/><w:sz w:val="22"/><w:lang w:val="ru-RU"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="140" w:line="280" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:basedOn w:val="Normal"/><w:pPr><w:spacing w:before="100" w:after="240"/></w:pPr><w:rPr><w:b/><w:color w:val="000000"/><w:sz w:val="36"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:pPr><w:keepNext/><w:spacing w:before="240" w:after="120"/><w:outlineLvl w:val="0"/></w:pPr><w:rPr><w:b/><w:color w:val="000000"/><w:sz w:val="26"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:basedOn w:val="Normal"/><w:rPr><w:color w:val="777777"/><w:sz w:val="18"/></w:rPr></w:style></w:styles>'
  };
  return zipFiles(files);
}
function downloadDocument(doc){if(!doc)return;downloadBlob(makeDocx(doc),doc.title.replace(/[<>:"/\\|?*]/g,'_').slice(0,80)+'.docx');toast(L('DOCX подготовлен к скачиванию.','DOCX жүктеуге дайын.'));}
function exportAnalytics(){
  const rows=[[L('Студент','Студент'),L('Группа','Топ'),L('Результат, %','Нәтиже, %'),L('Посещаемость, %','Қатысу, %'),L('Пройдено тестов','Өтілген тесттер')],...studentsData().map(s=>[s.name,s.group,s.score,s.attendance,s.tests])];
  const files={
    '[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>',
    '_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
    'xl/workbook.xml':`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${L('Успеваемость','Үлгерім')}" sheetId="1" r:id="rId1"/></sheets></workbook>`,
    'xl/_rels/workbook.xml.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>',
    'xl/worksheets/sheet1.xml':`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="28" customWidth="1"/><col min="2" max="2" width="16" customWidth="1"/><col min="3" max="5" width="23" customWidth="1"/></cols><sheetData>${rows.map((row,i)=>`<row r="${i+1}">${row.map((value,j)=>typeof value==='number'?`<c r="${String.fromCharCode(65+j)}${i+1}"><v>${value}</v></c>`:`<c r="${String.fromCharCode(65+j)}${i+1}" t="inlineStr"><is><t>${xml(value)}</t></is></c>`).join('')}</row>`).join('')}</sheetData><autoFilter ref="A1:E${rows.length}"/></worksheet>`
  };downloadBlob(zipFiles(files),'ORBIT-'+(state.analyticsGroup==='all'?'all':state.analyticsGroup)+'.xlsx');toast(L('Отчёт Excel подготовлен.','Excel есебі дайын.'));
}
function printDocument(doc){if(!doc)return;state.modalDocument=doc;openModal(e(doc.title),L('В окне печати выберите «Сохранить как PDF»','Басып шығару терезесінде «PDF ретінде сақтау» таңдаңыз'),`<article class="document-preview">${doc.html}</article>`,btn(L('Печать / PDF','Басып шығару / PDF'),'print-modal','','print'),true);requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));}

function helpModal(){const teacher=role().pages.includes('materials');const steps=[
  [L('Начните с обзора','Шолудан бастаңыз'),L('Покажите персональное пространство, календарь и быстрые инструменты.','Жеке кеңістікті, күнтізбені және жылдам құралдарды көрсетіңіз.')],
  [L('Создайте учебный материал','Оқу материалын жасаңыз'),L('Выберите HTML и CSS, Python или SQL. Покажите прогресс и готовый документ. Скачайте DOCX.','HTML және CSS, Python немесе SQL таңдаңыз. Прогресс пен дайын құжатты көрсетіңіз. DOCX жүктеңіз.')],
  [L('Переключитесь на студента','Студентке ауысыңыз'),L('Выберите роль справа вверху, задайте вопрос тьютору и пройдите тест.','Жоғарғы оң жақта рөлді таңдап, тьюторға сұрақ қойып, тестті өтіңіз.')],
  [L('Покажите результаты','Нәтижелерді көрсетіңіз'),L('Вернитесь к преподавателю, откройте аналитику и скачайте Excel.','Оқытушыға оралып, талдауды ашыңыз және Excel жүктеңіз.')],
  [L('Завершите управлением','Басқарумен аяқтаңыз'),L('Роль администратора позволяет добавить пользователя и показать настройки.','Әкімші рөлі пайдаланушы қосуға және баптауларды көрсетуге мүмкіндік береді.')]
];openModal(L('Готово к показу','Көрсетуге дайын'),L('Короткий маршрут на 3–5 минут','3–5 минутқа қысқа маршрут'),`<div class="help-steps">${steps.map(([title,text])=>`<div class="help-step"><div><strong>${title}</strong>${text}</div></div>`).join('')}</div>`,btn(L('Начать с обзора','Шолудан бастау'),'help-start','','arrow'));}
function aboutModal(){openModal('ORBIT · Education Space',L('Автономная демонстрация для колледжа','Колледжге арналған автономды демонстрация'),`<div class="help-steps"><div class="help-step"><div><strong>${L('Открывается одним файлом','Бір файлмен ашылады')}</strong>${L('Не требует сервера, установки или интернета. Можно перенести на флешке.','Сервер, орнату немесе интернет қажет емес. Флешкамен көшіруге болады.')}</div></div><div class="help-step"><div><strong>${L('Можно нажимать и исследовать','Басып, зерттеуге болады')}</strong>${L('Навигация, роли, языки, тесты и экспорт работают. Документы и результаты сохраняются в этом браузере.','Навигация, рөлдер, тілдер, тесттер және экспорт жұмыс істейді. Құжаттар мен нәтижелер осы браузерде сақталады.')}</div></div><div class="help-step"><div><strong>${L('ИИ показан через сценарии','ЖИ сценарийлер арқылы көрсетілген')}</strong>${L('Генерация и чат используют локальные примеры. Авторизация, RAG, сервер и реальная обработка PDF/DOCX/XLSX в этот демо-проект не входят.','Генерация мен чат жергілікті мысалдарды қолданады. Авторизация, RAG, сервер және PDF/DOCX/XLSX өңдеу бұл демо-жобаға кірмейді.')}</div></div></div>`,btn(L('Понятно','Түсінікті'),'close-modal','','check'));}
function notificationsModal(){openModal(L('Уведомления','Хабарламалар'),L('Пример событий в пространстве колледжа','Колледж кеңістігіндегі оқиғалар үлгісі'),[[L('Обновлён шаблон краткосрочного плана','Қысқа мерзімді жоспар үлгісі жаңартылды'),L('Методист · сегодня, 09:15','Әдіскер · бүгін, 09:15'),'file'],[L('Группа ПО-23-1 завершила тестирование','БҚ-23-1 тобы тестті аяқтады'),L('Демо-событие · сегодня, 08:40','Демо-оқиға · бүгін, 08:40'),'checklist'],[L('Добро пожаловать в Orbit','Orbit кеңістігіне қош келдіңіз'),L('Все инструменты уже готовы к исследованию','Барлық құралдар зерттеуге дайын'),'orbit']].map(([text,time,name])=>`<div class="notification-item"><span class="tool-icon" style="margin:0;flex-shrink:0;background:#e8eedd">${icon(name)}</span><div><p>${text}</p><small>${time}</small></div></div>`).join(''));}
function resetDemo(){cancelGeneration(false);clearTimeout(state.chatTimer);clearTimeout(state.toastTimer);try{localStorage.removeItem(STORE);}catch(_){}Object.assign(state,{documents:[],favorites:[],results:[],history:{ru:[],kz:[]},users:null,settings:{audit:true,template:true},preview:null,quiz:null,quizResult:null,chatBusy:false,formDrafts:{},role:'teacher',lang:'ru',page:'overview',search:'',libraryFilter:'all'});closeModal();persist();render();toast('Демонстрация восстановлена.');}

document.addEventListener('click',event=>{
  const target=event.target.closest('[data-page],[data-action],[data-lang]');
  if(!target){if(event.target.classList.contains('modal-overlay'))closeModal();if(!event.target.closest('.sidebar,.menu-toggle'))$('#sidebar')?.classList.remove('open');return;}
  if(target.disabled)return;
  if(target.dataset.page){navigate(target.dataset.page);return;}
  if(target.dataset.lang){
    const next=target.dataset.lang;if(next===state.lang)return;
    if(state.quiz){openModal(L('Сменить язык?','Тілді ауыстыру керек пе?'),L('Текущая попытка теста будет закрыта без сохранения','Ағымдағы тест әрекеті сақталмай жабылады'),'',`${btn(L('Продолжить тест','Тестті жалғастыру'),'close-modal','secondary')}${btn(L('Сменить язык','Тілді ауыстыру'),'confirm-lang','','arrow',`data-next="${next}"`)}`);return;}
    captureDraft();cancelGeneration(false);state.lang=next;persist();render();return;
  }
  const {action,id}=target.dataset;
  switch(action){
    case 'go':navigate(target.dataset.target);break;
    case 'menu':$('#sidebar').classList.toggle('open');break;
    case 'close-modal':closeModal();break;
    case 'confirm-lang':state.quiz=null;state.quizResult=null;state.lang=target.dataset.next;closeModal();persist();render();break;
    case 'about':aboutModal();break;
    case 'help':helpModal();break;
    case 'help-start':closeModal();navigate('overview');break;
    case 'notifications':notificationsModal();break;
    case 'calendar-day':state.selectedDay=Number(target.dataset.day);$('.calendar-panel').innerHTML=renderCalendar();break;
    case 'calendar-month':{const date=new Date(state.year,state.month+Number(target.dataset.dir),1);state.month=date.getMonth();state.year=date.getFullYear();state.selectedDay=1;$('.calendar-panel').innerHTML=renderCalendar();break;}
    case 'generator-type':captureDraft();cancelGeneration(false);if(state.page==='programmes')state.programmeType=target.dataset.type;else state.materialType=target.dataset.type;render();break;
    case 'sample':{const options=generatorOptions();if(options){state.preview=makePreview(options);$('#preview-panel').innerHTML=renderPreview(state.page==='programmes');}break;}
    case 'cancel-generation':cancelGeneration();break;
    case 'save-preview':savePreview();break;
    case 'download-preview':downloadDocument(state.preview);break;
    case 'print-preview':printDocument(state.preview);break;
    case 'open-doc':showDocument(id);break;
    case 'download-modal':downloadDocument(state.modalDocument);break;
    case 'print-modal':window.print();break;
    case 'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];persist();if($('#library-cards'))$('#library-cards').innerHTML=libraryCards();break;
    case 'library-filter':state.libraryFilter=target.dataset.filter;render();break;
    case 'upload-modal':uploadModal();break;
    case 'ask':askQuestion(target.dataset.question);break;
    case 'new-chat':clearTimeout(state.chatTimer);state.chatBusy=false;state.history[state.lang]=[];persist();render();toast(L('Новый диалог готов.','Жаңа диалог дайын.'));break;
    case 'create-test':createTestModal();break;
    case 'start-test':startTest(target.dataset.key);break;
    case 'answer':state.quizAnswers[state.quizIndex]=Number(target.dataset.answer);render();break;
    case 'quiz-back':if(state.quizIndex>0){state.quizIndex--;render();}break;
    case 'quiz-next':if(state.quizAnswers[state.quizIndex]===undefined)break;if(state.quizIndex<4){state.quizIndex++;render();}else finishQuiz();break;
    case 'exit-quiz':openModal(L('Завершить попытку?','Әрекетті аяқтау керек пе?'),L('Ответы этой попытки не будут сохранены','Осы әрекеттің жауаптары сақталмайды'),'',`${btn(L('Продолжить','Жалғастыру'),'close-modal','secondary')}${btn(L('Выйти из теста','Тесттен шығу'),'back-tests','','arrow')}`);break;
    case 'back-tests':closeModal();state.quiz=null;state.quizResult=null;render();break;
    case 'export-analytics':exportAnalytics();break;
    case 'add-user':if(state.role==='admin')userModal();break;
    case 'edit-user':if(state.role==='admin')userModal(id);break;
    case 'toggle-user':if(state.role==='admin'){const user=getUsers().find(u=>u.id===id);if(user){user.active=!user.active;persist();render();toast(L('Статус пользователя обновлён.','Пайдаланушы күйі жаңартылды.'));}}break;
    case 'setting':state.settings[target.dataset.setting]=!state.settings[target.dataset.setting];persist();render();toast(L('Демонстрационная настройка сохранена.','Демонстрациялық баптау сақталды.'));break;
    case 'backup':downloadBlob(new Blob([JSON.stringify({version:1,documents:state.documents,results:state.results,users:getUsers(),history:state.history},null,2)],{type:'application/json'}),'ORBIT-backup.json');break;
    case 'reset-modal':openModal(L('Восстановить исходное демо?','Бастапқы демоны қалпына келтіру керек пе?'),L('Созданные документы, результаты тестов и диалоги будут удалены из браузера. Скачанные файлы останутся.','Жасалған құжаттар, тест нәтижелері және диалогтар браузерден өшіріледі. Жүктелген файлдар сақталады.'),'',`${btn(L('Отмена','Болдырмау'),'close-modal','secondary')}${btn(L('Сбросить','Қалпына келтіру'),'reset-confirm','danger','reset')}`);break;
    case 'reset-confirm':resetDemo();break;
  }
});
document.addEventListener('submit',event=>{
  const formId=event.target.getAttribute('id');
  if(!['generator-form','chat-form','user-form','upload-form','test-create-form'].includes(formId))return;
  event.preventDefault();
  if(formId==='generator-form')generate();
  if(formId==='chat-form')askQuestion($('#chat-input').value);
  if(formId==='user-form'&&state.role==='admin')saveUser(event.target);
  if(formId==='upload-form')importText(event.target);
  if(formId==='test-create-form')startTest(event.target.elements.quizTopic.value);
});
document.addEventListener('change',async event=>{
  const target=event.target;
  if(target.id==='role-select'){
    captureDraft();cancelGeneration(false);state.role=target.value;state.page='overview';state.quiz=null;state.quizResult=null;state.preview=null;persist();render();toast(L('Роль изменена. Доступные разделы обновлены.','Рөл өзгертілді. Қолжетімді бөлімдер жаңартылды.'));
  }
  if(target.id==='analytics-group'){state.analyticsGroup=target.value;render();}
  if(target.id==='analytics-period'){state.analyticsPeriod=target.value;render();}
  if(target.id==='text-file'&&target.files[0]){
    const file=target.files[0];if(file.size>150000){toast(L('Для демо выберите текстовый файл до 150 КБ.','Демо үшін 150 КБ-қа дейінгі мәтіндік файл таңдаңыз.'));return;}
    try{const text=await file.text();if($('#field-text')){$('#field-text').value=text.slice(0,30000);$('#field-title').value=file.name.replace(/\.(txt|md)$/i,'');toast(L('Текст загружен. Нажмите «Сохранить».','Мәтін жүктелді. «Сақтау» басыңыз.'));}}catch(_){toast(L('Не удалось прочитать файл.','Файлды оқу мүмкін болмады.'));}
  }
});
document.addEventListener('input',event=>{if(event.target.id==='library-search'){state.search=event.target.value;if($('#library-cards'))$('#library-cards').innerHTML=libraryCards();}});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'){if($('#modal-root').firstElementChild)closeModal();else $('#sidebar').classList.remove('open');}
  if(event.key==='Enter'&&event.target.id==='chat-input'&&!event.shiftKey){event.preventDefault();askQuestion(event.target.value);}
  if(event.key==='Tab'&&$('#modal-root').firstElementChild){const controls=$$('.modal button:not([disabled]),.modal input:not([type="hidden"]),.modal select,.modal textarea,.modal [tabindex="0"]');const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
render();
